<?php

namespace App\Platform\Identity\Otp;

/**
 * The current in-house OTP path, extracted behind the provider port
 * (S46, behavior-identical): codes are generated by the caller's own
 * CodeSource (module seam — SeededOtpCodes in tests keeps the
 * deterministic drill), recorded against the challenge id, compared by
 * constant-time hash. This is also the production provider for the
 * platform/step-up audience — Firebase never touches it.
 */
final class LocalCodeProvider implements PhoneVerificationProvider
{
    public const NAME = 'local';

    public function __construct(private readonly CodeSource $codes)
    {
    }

    public function name(): string
    {
        return self::NAME;
    }

    public function send(OtpSendContext $context): OtpSendResult
    {
        $code = $this->codes->generate($context->codeLength);
        $this->codes->record($context->challengeId, $code);

        return new OtpSendResult(code: $code);
    }

    public function verify(OtpVerifyRequest $request): OtpVerifyOutcome
    {
        // No hash on the row: fail closed as a mismatch (a local row
        // without a hash must never be redeemable).
        if ($request->codeHash === null) {
            return OtpVerifyOutcome::Mismatch;
        }

        return hash_equals($request->codeHash, hash('sha256', $request->code))
            ? OtpVerifyOutcome::Match
            : OtpVerifyOutcome::Mismatch;
    }
}
